import csv,glob,re
for f in sorted(glob.glob('terminology-pass/*/equivalents.tsv')):
    for r in csv.DictReader(open(f),delimiter='\t'):
        t=r['scope_note']+' || '+r['conflation_note']
        refs=set(re.findall(r'R2-\d{3}',t))-{r['concept_id']}
        if refs or r['concept_id'] in ('','NOT-IN-REGISTER','NOT-IN-REGISTER-2'):
            print(f.split('/')[1],r['concept_id'],'|',r['form'],'|',t[:260])
PY

